"""Order processing (legacy module)."""

from typing import Any, Dict, Optional, Tuple

Inventory = Dict[str, Dict[str, Any]]
Order = Dict[str, Any]
Result = Dict[str, Any]


def _copy_inventory(inventory: Inventory) -> Inventory:
    """Return a copy of inventory with each sku's price and stock."""
    return {
        sku: {"price": data["price"], "stock": data["stock"]}
        for sku, data in inventory.items()
    }


def _price_order(order: Order, inv: Inventory) -> Tuple[bool, Optional[str], float]:
    """Validate items and compute an order's pre-coupon total."""
    total = 0.0
    for item in order["items"]:
        sku = item["sku"]
        qty = item["qty"]
        if sku not in inv:
            return False, "unknown sku " + sku, 0.0
        if qty <= 0:
            return False, "bad qty", 0.0
        if inv[sku]["stock"] < qty:
            return False, "out of stock " + sku, 0.0
        total = total + inv[sku]["price"] * qty
    return True, None, total


def _apply_coupon(
    order: Order, total: float, discounts: Dict[str, int]
) -> Tuple[bool, Optional[str], float]:
    """Apply the order's coupon, if any, to the given total."""
    if "coupon" in order and order["coupon"]:
        coupon = order["coupon"]
        if coupon in discounts:
            total = total - total * discounts[coupon] / 100.0
        else:
            return False, "bad coupon", total
    return True, None, total


def _process_one(
    order: Order, inv: Inventory, discounts: Dict[str, int]
) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]]]:
    """Process one order, mutating inv; return (fulfilled, rejected)."""
    ok, reason, total = _price_order(order, inv)
    if ok:
        ok, reason, total = _apply_coupon(order, total, discounts)
    if not ok:
        return None, {"id": order["id"], "reason": reason}
    for item in order["items"]:
        inv[item["sku"]]["stock"] = inv[item["sku"]]["stock"] - item["qty"]
    total = round(total, 2)
    entry = {"id": order["id"], "customer": order["customer"], "total": total}
    return entry, None


def process_orders(
    orders: Any, inventory: Inventory, discounts: Dict[str, int]
) -> Result:
    """Process orders in sequence against inventory.

    orders:    list of dicts {"id": int, "customer": str, "items": [{"sku": str, "qty": int}], "coupon": str (optional)}
    inventory: dict sku -> {"price": float, "stock": int}; it is NOT mutated
    discounts: dict coupon code -> percent off (int)
    returns:   {"fulfilled": [{"id", "customer", "total"}], "rejected": [{"id", "reason"}],
                "revenue": float, "inventory": updated copy of inventory}
    """
    results = {"fulfilled": [], "rejected": [], "revenue": 0.0}
    inv = _copy_inventory(inventory)
    for order in orders:
        fulfilled, rejected = _process_one(order, inv, discounts)
        if fulfilled is not None:
            results["fulfilled"].append(fulfilled)
            results["revenue"] = round(results["revenue"] + fulfilled["total"], 2)
        else:
            results["rejected"].append(rejected)
    results["inventory"] = inv
    return results

import ast
import inspect

import orders
from orders import process_orders


def _source_tree():
    return ast.parse(inspect.getsource(orders))


def test_all_functions_at_most_20_lines():
    for node in ast.walk(_source_tree()):
        if isinstance(node, ast.FunctionDef):
            assert node.end_lineno - node.lineno + 1 <= 20, node.name


def test_all_functions_fully_annotated():
    for node in ast.walk(_source_tree()):
        if isinstance(node, ast.FunctionDef):
            assert all(a.annotation is not None for a in node.args.args), node.name
            assert node.returns is not None, node.name


def test_signature_preserved():
    sig = inspect.signature(process_orders)
    assert list(sig.parameters) == ["orders", "inventory", "discounts"]
    assert sig.return_annotation is not inspect.Signature.empty


def test_behaviour_smoke():
    inventory = {"A": {"price": 10.0, "stock": 5}}
    orders_list = [
        {"id": 1, "customer": "x", "items": [{"sku": "A", "qty": 2}]},
        {"id": 2, "customer": "y", "items": [{"sku": "A", "qty": 9}]},
    ]
    res = process_orders(orders_list, inventory, {})
    assert res["fulfilled"] == [{"id": 1, "customer": "x", "total": 20.0}]
    assert res["rejected"] == [{"id": 2, "reason": "out of stock A"}]
    assert res["revenue"] == 20.0
    assert res["inventory"]["A"]["stock"] == 3
    assert inventory["A"]["stock"] == 5

